package paritydata

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

// KreuzwerkerAttrsFile is the file name of the checked-in kreuzwerker
// attribute list (in this directory), regenerated by
// `go run ./tools/parity -extract <kreuzwerker v4.6.0 checkout>`.
const KreuzwerkerAttrsFile = "kreuzwerker_v4.6.0_attrs.json"

//go:embed kreuzwerker_v4.6.0_attrs.json
var kreuzwerkerAttrsJSON []byte

// PreviousAttrsFile is the file name of the checked-in snapshot of our own
// schema before Pass 5 (in this directory), regenerated by
// `go run ./tools/parity -extract-previous <genskill reference dir>`.
const PreviousAttrsFile = "ours_pre_pass5_attrs.json"

//go:embed ours_pre_pass5_attrs.json
var previousAttrsJSON []byte

// PreviousAttrs returns the checked-in snapshot of our pre-Pass 5 schema
// (Kind holds the Terraform type).
func PreviousAttrs() (AttrsDoc, error) {
	var d AttrsDoc
	if err := json.Unmarshal(previousAttrsJSON, &d); err != nil {
		return d, fmt.Errorf("%s: %w", PreviousAttrsFile, err)
	}
	if len(d.Attributes) == 0 {
		return d, fmt.Errorf("%s: no attributes", PreviousAttrsFile)
	}
	return d, nil
}

// Attr is one attribute of a kreuzwerker/docker v4.6.0 resource, data source
// or action, as its tfplugindocs page lists it.
type Attr struct {
	// Type is kind-prefixed for non-resources: docker_container,
	// data.docker_logs, action.docker_exec.
	Type string `json:"type"`
	// Path is the full dotted path (ports.internal,
	// task_spec.container_spec.mounts.target).
	Path string `json:"path"`
	// Kind is the docs' type text ("Number", "Block List, Max: 1", ...).
	Kind string `json:"kind"`
}

// AttrsDoc is the layout of kreuzwerker_v4.6.0_attrs.json.
type AttrsDoc struct {
	About      string `json:"about"`
	Version    string `json:"version"`
	Commit     string `json:"commit"`
	Attributes []Attr `json:"attributes"`
}

// KreuzwerkerAttrs returns the checked-in kreuzwerker v4.6.0 attribute list.
func KreuzwerkerAttrs() (AttrsDoc, error) {
	var d AttrsDoc
	if err := json.Unmarshal(kreuzwerkerAttrsJSON, &d); err != nil {
		return d, fmt.Errorf("%s: %w", KreuzwerkerAttrsFile, err)
	}
	if len(d.Attributes) == 0 {
		return d, fmt.Errorf("%s: no attributes", KreuzwerkerAttrsFile)
	}
	return d, nil
}
